    "s19_c1_desc": "Maximaler Punch, kraftvoller Attack, extrem formstabil",
    "s19_c2_desc": "Brillant, transparent, differenzierter obertonreicher Ton",
    "s19_c3_desc": "Warmer, samtiger Grundton, volles Bassfundament",
    "s19_c4_desc": "Geringe Trägheit, singender Diskant, leichte Ansprache",
