    "s20_c1_title": "Symmetrische Standardformen",
    "s20_c2_title": "Asymmetrische Sonderformen",
    "s20_c1_desc": "Für Steinway & Sons (historisch und modern), Bösendorfer, Schimmel, C. Bechstein, Yamaha, Kawai, Grotrian-Steinweg, Petrof, August Förster, Sauter, Blüthner und Renner USA.",
    "s20_c2_desc": "Alt-Bechstein Konstruktionen, Flügel mit extrem schlankem Diskantverlauf sowie Spezialprofile zur Anpassung des Trägheitsmoments an steile Saitenwinkel.",
    "s20_caption_1": "Moulding Types: Vielfalt der Kernholz-Profile im Renner Sortiment",
