    "s5_hl1_title": "Exclusive Wool Blend:",
    "s5_hl1_desc": "Exclusive felt blend from select wools sourced from Argentina, South Africa, and New Zealand: Only the precise combination of long fine fibers and strongly interlocking wools yields this extremely tensile, resilient hammer felt.",
