    "s5_c1_title": "The Secret of Weickert Felt",
    "s5_c1_desc": "Purely mechanical fulling without chemical additives – the acoustic soul of the concert grand",
    "s5_notes": "Slide 5: Company history of Filzfabrik Wurzen (FFW) in Wurzen from 1783 to the present and the acoustic secret of Weickert felt. Introduce the 6 historical milestones: 1783 founding in Wurzen by J.D. Weickert, 1847 invention of Germany's first viable piano felt (replacing leather hammer covers), 1850-1867 London & Paris World Expos with royal honors, 1861 industrial expansion at Wurzen Mühlgraben with steam engines and soft Mulde water, 1906 world leader for 200,000 pianos annually (Steinway New York), and today the renaissance of 'Weickert Spezial' exclusively for Louis Renner. Strongly emphasize the close geographical proximity between Filzfabrik Wurzen and the Renner factory in Meuselwitz (just ~65 km): enabling direct master-to-master dialogue, resilient supply chains, and perfect acoustic tuning.",
    "s6_category": "Part 2: Felt Manufacturing • Rohstoff & Wolle",
    "s6_title": "Pure Virgin Wool: Preserving Natural Fiber Elasticity",
    "s6_subtitle": "Only uncompressed raw wool guarantees maximum natural elasticity",
    "s6_bullet_1": "<strong>Bale Delivery Without Over-Compression:</strong> Raw wool is transported in loosely packed bales. Excessive compression would irreversibly damage the delicate scales and crimp of the wool fibers.",
    "s6_bullet_2": "<strong>Higher Logistics Costs for Supreme Quality:</strong> This gentle handling increases transport volume, but safeguards intact fiber elasticity.",
    "s6_bullet_3": "<strong>Pronounced Fiber Crimp:</strong> Only highly crimped Merino wool fibers provide optimal interlocking during the subsequent fulling process.",
    "s6_bullet_4": "<strong>Gentle Carbonization:</strong> A chemically gentle cleansing process removes plant matter without attacking the keratin protein structure.",
    "s6_caption_1": "Raw wool delivery: Gently stored wool bales at FFW",
    "s6_b1_badge": "RAW MATERIAL SELECTION",
    "s6_b2_badge": "UNPRESSED BALES",
    "s6_panel_title": "Selection of fine overseas Merino wool",
    "s6_panel_subtitle": "Gentle transport in uncompressed bales preserves microscopic scale structure",
    "s6_fact_badge": "🐑 100% pure virgin Merino wool without synthetic additives",
    "s6_spotlight_badge": "FIBER INTEGRITY",
    "s6_spotlight_title": "The Natural Power of Keratin",
    "s6_spotlight_desc": "Intact scale structure determines the hammerhead's ultimate strike elasticity",
