    "s6_hl1_desc": "Gentle organic cleansing removes plant residues without damaging keratin protein structure.",
    "s6_hl2_title": "Natural Spiral Springs:",
    "s6_hl2_desc": "Millions of fine crimps absorb string strike in milliseconds.",
    "s6_hl3_title": "Pure Wool Grease (Lanolin):",
    "s6_hl3_desc": "Preserves suppleness and guards against brittleness during climate swings.",
