    "s8_category": "Part 2: Felt Manufacturing • Vlies & Faserrichtung",
    "s8_title": "Carding: Parallel Alignment into Flowing Fleece",
    "s8_subtitle": "Defined fiber orientation as the foundation for resonance and string response",
    "s8_bullet_1": "<strong>Carding:</strong> Loosened fibers are combed through fine wire rollers, untangled, and arranged in parallel alignment.",
    "s8_bullet_2": "<strong>Defined Fiber Direction:</strong> The resulting gossamer-thin, soft web features a precisely specified preferential fiber orientation.",
    "s8_bullet_3": "<strong>Layering:</strong> Multiple web layers are superimposed in cross-lap and longitudinal arrangements to build the required sheet thickness and density gradient.",
    "s8_bullet_4": "<strong>Prerequisite for Voicing:</strong> Only parallel-aligned fibers react predictably and evenly to voicing needle penetration during subsequent tone regulation.",
    "s8_caption_1": "Carding wool into silky flowing webs with defined fiber orientation",
    "s8_b1_badge": "FIBER ORIENTATION",
    "s8_b2_badge": "CARDING & FLEECE",
