    "s8_spotlight_title": "Prerequisite for Voicing",
    "s8_spotlight_desc": "Only parallel fibers respond predictably and uniformly to needle strokes in subsequent voicing",
    "s8_texture_tag": "Fleece Web: Ordered Fibers",
