    "s11_subtitle": "Final dimensional calibration without sanding – preserving the silky fiber cuticle",
    "s11_bullet_1": "<strong>Mechanical Hammering:</strong> Specialized felt hammers and polished natural stones consolidate sheets to exact target dimensions.",
    "s11_bullet_2": "<strong>Zero Sanding:</strong> Sanding felt shears off millions of natural fibers. The Weickert process completely eliminates surface grinding or sanding.",
    "s11_bullet_3": "<strong>Smooth Bending Radius:</strong> When wrapped around the hammer moulding, the felt surface remains completely intact and smooth – without tearing or slipping apart.",
