    "s15_subtitle": "Computer-controlled cutting lines with micro-stepper motors and laser guidance",
    "s15_bullet_1": "<strong>Tapered Strip Cutting:</strong> Micro-stepper motors guide the blade along the exact wedge profile (thick bass to thin treble).",
    "s15_bullet_2": "<strong>Laser Line Guidance:</strong> Real-time laser projection monitors cutting paths with tolerance under 0.05 mm.",
    "s15_bullet_3": "<strong>Individual Customer Tapers:</strong> Continuous wedge angles can be configured for every manufacturer and scale design.",
    "s15_bullet_4": "<strong>Industry 4.0 in Piano Making:</strong> Digital traceability from raw wool bale to finished hammerhead.",
    "s15_caption_1": "Modern robotic felt cutting center at the Meuselwitz plant",
    "s15_b1_badge": "ROBOTICS",
    "s15_b2_badge": "FACTORY VIDEO MEUSELWITZ",
    "s15_notes": "Slide 15: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s16_category": "Part 3: Hammerkopf-Produktion • Deckfilz-Qualität",
    "s16_title": "Edge Quality & Fiber Integrity in Top Felt Strips",
    "s16_subtitle": "Razor-sharp vertical cuts prevent skewed stretching during hammer moulding",
    "s16_bullet_1": "<strong>100% Vertical Cut Edge:</strong> Prevents distortion and uneven fiber elongation during subsequent high-pressure pressing.",
    "s16_bullet_2": "<strong>No Crushed Fibers:</strong> Clean cutting preserves internal fiber voids, ensuring unconstrained compression dynamics.",
    "s16_bullet_3": "<strong>Prevention of Skewing:</strong> Only strictly rectangular cut strips wrap around the wooden moulding with absolute lateral symmetry.",
    "s16_caption_1": "Inspected top felt strip: Tapered profile and homogeneous fiber matrix",
    "s16_b1_badge": "QUALITY CONTROL",
    "s16_b2_badge": "TOP FELT STRIPS",
    "s16_c1_desc": "Following high-precision robotic cutting, every felt strip undergoes strict optical inspection.",
    "s16_notes": "Slide 16: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s17_category": "Part 3: Hammerkopf-Produktion • Unterfilz",
    "s17_title": "Underfelt Profiling: Base Foundation of Tension",
    "s17_subtitle": "Precision profiling of underfelt strips for optimal cushioning and energy transmission",
    "s17_bullet_1": "<strong>Function of Underfelt:</strong> Acts as an elastic buffer between the rigid wood moulding and resilient top felt.",
    "s17_bullet_2": "<strong>Precision Profiling:</strong> In Meuselwitz, underfelt strips are shaped on dedicated multi-axis milling machines prior to gluing.",
    "s17_bullet_3": "<strong>Even Pressure Distribution:</strong> The profiled contour ensures press clamping force flows smoothly into the hammer flanks.",
    "s17_caption_1": "Profiling the underfelt strip on specialized Renner milling machinery",
