    "s20_category": "Part 3: Hammerkopf-Produktion • Kern-Geometrie",
    "s20_title": "Core Wood Geometries: Symmetrical & Asymmetrical",
    "s20_subtitle": "Historic and modern profiles for over 20 grand and upright piano marques",
    "s20_c1_title": "Symmetrical Standard Profiles",
    "s20_c2_title": "Asymmetrical Custom Profiles",
    "s20_c1_desc": "For Steinway & Sons (historic and modern), Bösendorfer, Schimmel, C. Bechstein, Yamaha, Kawai, Grotrian-Steinweg, Petrof, August Förster, Sauter, Blüthner, and Renner USA.",
    "s20_c2_desc": "Historic Bechstein designs, grands with ultra-slender treble progressions, and custom mouldings balancing moment of inertia against steep string angles.",
    "s20_caption_1": "Moulding Types: Diversity of core wood profiles in the Renner catalogue",
    "s20_b1_badge": "SYMMETRICAL",
    "s20_b2_badge": "ASYMMETRICAL",
    "s20_b3_badge": ">CORE GEOMETRY",
    "s20_notes": "Slide 20: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s21_category": "Part 3: Hammerkopf-Produktion • Vorformung",
    "s21_title": "Bass Felt Pre-Forming & Bending Curvatures",
    "s21_subtitle": "Developing characteristic tension arches before closing the press",
    "s21_bullet_1": "<strong>Elastic Pre-Bending:</strong> The heavy bass end of the felt strip is pre-conditioned before loading into the press fixture.",
    "s21_bullet_2": "<strong>Characteristic Contours:</strong> Harmonious wave profiles form along the strip, mirroring subsequent pressure vectors.",
    "s21_bullet_3": "<strong>Uniform Elongation:</strong> Prevents outer fiber tearing when tightly encircling the apex of the wooden moulding.",
    "s21_caption_1": "Bass end of felt strip exhibiting characteristic pre-bending curves before pressing",
    "s21_b1_badge": "PRE-FORMING",
    "s21_b2_badge": "BENDING FORCE",
    "s21_notes": "Slide 21: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s22_category": "Part 3: Hammerkopf-Produktion • Pressprozess",
    "s22_title": "Pressing & Glueing: Tension & Compression Equilibrium",
    "s22_subtitle": "Re-tensioning the wooden moulding to build maximum elastic outer tension",
    "s22_bullet_1": "<strong>Closing Side Jaws:</strong> Temperature-controlled press jaws flank the felt and wrap it around the glued wooden moulding.",
    "s22_bullet_2": "<strong>Re-tensioning the Moulding:</strong> Once side jaws are closed, high hydraulic pressure re-tensions the core moulding downwards.",
    "s22_bullet_3": "<strong>Tensile Pre-Stress in Outer Layers:</strong> This proprietary Renner technique imparts unmatched dynamic pre-tension to outer felt layers.",
    "s22_bullet_4": "<strong>Foundation for Voicing:</strong> This elastic stored energy enables subsequent voicing with extraordinary dynamic range.",
    "s22_caption_1": "Hammerhead pressing and gluing process under high hydraulic pressure",
    "s22_b1_badge": "HIGH-PRESSURE PRESSING",
    "s22_b2_badge": "FACTORY VIDEO",
    "s22_notes": "Slide 22: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s23_category": "Part 3: Hammerkopf-Produktion • Hammerkopf-Riegel",
    "s23_title": "The Raw Hammerhead Moulding Bar after Pressing",
    "s23_subtitle": "De-moulding the monolithic 88-note block after glue cure",
    "s23_bullet_1": "<strong>Flawless Glue Line:</strong> Continuous bonding between wood, underfelt, and top felt with zero air pockets.",
    "s23_bullet_2": "<strong>Harmonious Transition:</strong> The moulding contour imprints crisply beneath the compacted felt envelope.",
    "s23_bullet_3": "<strong>Proprietary Thermo-Forming:</strong> Dedicated post-cure thermal stabilization remains a strictly guarded Renner trade secret.",
    "s23_caption_1": "The bonded hammerhead block immediately following de-moulding",
    "s23_b1_badge": "MOULD PRODUCTION",
    "s23_b2_badge": "PRESSED MOULD",
    "s23_c1_desc": "After controlled cooling and curing of the glue, the hammerheads are removed as a continuous molded block.",
    "s23_notes": "Slide 23: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s24_category": "Part 3: Hammerkopf-Produktion • CNC-Bearbeitung",
    "s24_title": "CNC Machining & Truing of the Moulding Bar",
    "s24_subtitle": "Multi-axis flank milling and slicing into 88 individual hammerheads",
    "s24_bullet_1": "<strong>CNC Truing of Blocks:</strong> Removal of glue beads and high-precision milling of outer moulding contours.",
    "s24_bullet_2": "<strong>High-Speed Milling:</strong> Specialized tooling cuts dense wool felt with razor-sharp edges without fiber pullout.",
    "s24_bullet_3": "<strong>Precision Slicing:</strong> Slicing the block into exact progressive widths (approx. 11.5 mm bass to 9.5–10 mm treble).",
    "s24_caption_1": "CNC precision milling center in Meuselwitz machining hammerhead blocks",
    "s24_b1_badge": "CNC DRESSING",
    "s24_b2_badge": "CNC MILLING",
    "s24_notes": "Slide 24: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s25_category": "Part 3: Hammerkopf-Produktion • Bohren & Vernieten",
    "s25_title": "Boring, T-Wire Riveting & Finishing",
    "s25_subtitle": "Precision shank boring at spatial angles and brass T-rivet insertion",
    "s25_bullet_1": "<strong>Automated Shank Boring:</strong> Boring at exact spatial angles (bore depth, diameter ø 5.4 mm, inclination in gon).",
    "s25_bullet_2": "<strong>T-Riveting:</strong> High-tensile brass T-rivets permanently secure felt flanks against bursting under fortissimo concert attacks.",
    "s25_bullet_3": "<strong>Tail Radiusing:</strong> Specially shaped tail profiles facilitate smooth engagement with the backcheck.",
    "s25_caption_1": "Boring and T-rivet insertion at the Meuselwitz facility",
    "s25_b1_badge": "FINISHING & FINAL TOUCH",
    "s25_b2_badge": "FACTORY VIDEO",
