    "s26_category": "Part 3: Hammerkopf-Produktion • Qualität & Nutzen",
    "s26_title": "6 Core Advantages of the New Renner Hammerheads",
    "s26_subtitle": "Executive summary of innovations presented by Clemens Kunert",
    "s26_c1_title": "1. Tailor-Made Fabrication",
    "s26_c2_title": "2. Ready for Final Voicing",
    "s26_c3_title": "3. Supreme Precision",
    "s26_c4_title": "4. Outstanding Tonal Stability",
    "s26_c5_title": "5. Rich Overtones",
    "s26_c6_title": "6. Drop-In Refinement",
    "s26_c1_desc": "Custom one-off fabrication for historic treasures through to major concert series runs.",
    "s26_c2_desc": "No time-consuming pre-voicing required at the piano! Sets arrive tonally pre-conditioned from the factory.",
    "s26_c3_desc": "Combining traditional FFW felt mastery with micrometer-level robotic and CNC precision.",
    "s26_c4_desc": "Thanks to the stored tension of Weickert Special felt, tonal response remains rock-solid for years.",
    "s26_c5_desc": "Widest dynamic range from the whisper of pianissimo to room-filling fortissimo projection.",
    "s26_c6_desc": "Bored to spec, securely riveted, with radiused tail ends and hand-inspected crown contours.",
    "s26_b1_badge": "CUSTOM-MADE",
    "s26_b2_badge": "EFFICIENCY",
    "s26_b3_badge": "PRECISION",
