    "s37_notes": "Closing slide of Chapter 4. Summarize the triple win for technicians, dealerships, and pianists.",
    "s38_category": "Part 5: Voicing • Geometrie & Keile",
    "s38_title": "The Clock Model: The 4 Dynamic Wedges",
    "s38_subtitle": "Structured hammerhead zoning by register and dynamic objectives",
