    "s38_notes": "Slide 38: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s39_category": "Part 5: Voicing • Vorintonation",
    "s39_title": "Pre-Voicing (Pre-Needling): Deep 90° Stitches in Blue Wedge",
    "s39_subtitle": "Relieving factory pre-tension and channeling elastic energy into the forte wedge",
    "s39_bullet_1": "<strong>Work Zone:</strong> Exclusively in the blue fortissimo wedge (clock zones 9:00–10:00 and 2:00–3:00).",
    "s39_bullet_2": "<strong>Deep Needling:</strong> Insert needles deeply to just short of the underfelt (never pierce underfelt or core wood!).",
    "s39_bullet_3": "<strong>Tension Transfer:</strong> The head sheds rigid factory stiffness; stored tension flows into the green forte wedge.",
    "s39_bullet_4": "<strong>Recommendation:</strong> This step is recommended almost without exception prior to first playing-in in the instrument.",
    "s39_caption_1": "Pre-needling: Deep stitches in the fortissimo wedge (9:00 to 10:00 o'clock)",
    "s39_b1_badge": "PRE-NEEDLING",
    "s39_b2_badge": "BASIC ELASTICITY",
    "s39_c1_desc": "Pre-voicing is the single most critical foundation for brand-new or refelted hammerheads:",
    "s39_notes": "Slide 39: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s40_category": "Part 5: Voicing • Werkzeug & Technik",
    "s40_title": "Needle Insertion Standards & Voicing Tools",
    "s40_subtitle": "Press, do not chop – Exact stitch counts for bass, mid-range, and treble",
    "s40_bullet_1": "<strong>Stitch Counts for Pre-Needling:</strong> <br>• Bass: 7–10 stitches horizontally <br>• Mid-Range: 5–10 stitches horizontally <br>• Treble: 0–7 stitches vertically",
    "s40_bullet_2": "<strong>Press, never chop!</strong> Press needles steadily using body weight. Chopping tears wool fibers uncontrollably!",
    "s40_bullet_3": "<strong>Original Renner Tools:</strong> <br>• Adjustable Voicing Tool (item 43-0005642) <br>• 3-Needle Voicing Tool Professional (item 43-0003270) <br>• Nickel-plated needles no. 7 ø 0.60 mm, 9 mm long (item 43-0003426).",
    "s40_caption_1": "Renner voicing tools, needle handles, and adjustable voicing instrument",
    "s40_b1_badge": "TOOL SET",
    "s40_b2_badge": "PRECISION NEEDLES",
    "s40_notes": "Slide 40: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s41_category": "Part 5: Voicing • Saitenlagerung",
    "s41_title": "String Preparation: Hitch Pins, Bridge Pins & Leveling",
    "s41_subtitle": "“The finest hammerhead can only reveal what is programmed into the instrument!”",
    "s41_caption_1": "Bedding strings firmly at the hitch pin using brass drift punch",
    "s41_b1_badge": "STRING BEDDING",
    "s41_b2_badge": "UNISON PURITY",
    "s41_bullet_1": "<strong>Setting Hitch Pins:</strong> Carefully seat strings from back to front at hitch pins using a brass drift punch and light hammer.",
    "s41_bullet_2": "<strong>Bridge Pin Alignment:</strong> Seat strings on the bridge with Renner bridge punch to eliminate false beats.",
    "s41_bullet_3": "<strong>Unison Purity:</strong> Before the first voicing needle, the unison must ring absolutely pure and free of unwanted friction.",
    "s41_notes": "Slide 41: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s42_category": "Part 5: Voicing • Ausrichtung",
    "s42_title": "Treble Strike Point Alignment & Hammer Straightness",
    "s42_subtitle": "Optimizing notes 69–88 by micro-shifting the keyframe strike line",
    "s42_bullet_1": "<strong>Test Strike Point on Note 88:</strong> Shift keyframe slightly forward and back to locate the brightest, most singing treble sweet spot.",
    "s42_bullet_2": "<strong>Optimize Notes 69 to 88:</strong> The high treble on many grands improves dramatically once the strike line is precisely repositioned!",
    "s42_bullet_3": "<strong>Squareness of All Hammers:</strong> Test by plucking strings or lifting jacks with finger; mark corrections with chalk on key tops.",
    "s42_caption_1": "Verifying treble strike point and square alignment of hammerheads",
    "s42_b1_badge": "STRIKE POINT",
    "s42_b2_badge": "TREBLE BRILLIANCE",
    "s42_notes": "Slide 42: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s43_category": "Part 5: Voicing • Kronenabzug",
    "s43_title": "Crown Filing: Concave, Correct or Tilted",
    "s43_subtitle": "Adapting the strike crown to the 3-string unison using a fine hammer file",
    "s43_c1_title": "Hollow Crown",
    "s43_c2_title": "Crooked Crown",
    "s43_c3_title": "Level & Symmetrical (Crown OK)",
    "s43_c1_desc": "Crown contacts only outer strings -> incomplete attack tone, must be filed level.",
    "s43_c2_desc": "Asymmetrical contact creates double attack and string buzz -> file true to string plane.",
    "s43_c3_desc": "Simultaneous solid contact on all 3 unison strings for a full fundamental tone.",
    "s43_caption_1": "Filing hammer crowns for perfect flush alignment to 3-string unisons",
    "s43_b1_badge": "HOLLOW BEFORE ROUND",
    "s43_b2_badge": "CROWN APEX",
    "s43_b3_badge": ">SANDING PADDLE",
    "s43_notes": "Slide 43: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s44_category": "Part 5: Voicing • Feinabstimmung",
    "s44_title": "Intermediate & Fine Voicing: The 2 mm Limit at the Crown",
    "s44_subtitle": "Chromatic listening and delicate evening-out of individual notes",
    "s44_bullet_1": "<strong>Chromatic Play-Through:</strong> Play chromatically up and down the keyboard; flag notes with harsh attack or uneven volume.",
    "s44_bullet_2": "<strong>Mid-Voicing:</strong> Gentle needle pricks in green forte and orange piano wedges. Overly soft notes are firmed by light surface sanding!",
    "s44_bullet_3": "<strong>Final Voicing:</strong> Short single needle (BDK handle item 43-0003269 or Chop Stick item 43-0003271).",
    "s44_bullet_4": "<strong>Max. 2 mm Depth at Crown:</strong> Insert only between string grooves, never directly into the string depressions!",
    "s44_caption_1": "Chromatic listening and fine voicing with short single needle",
    "s44_b1_badge": "FINE VOICING",
    "s44_b2_badge": "COLOR PALETTE",
    "s44_notes": "Slide 44: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
