    "s1_title": "LOUIS RENNER",
    "s1_subtitle": "ピアノの心臓部：140年の伝統、モイゼルヴィッツ新拠点、そして至高のハンマーヘッド製造技術",
    "s1_kicker": "レンナー・マスタークラス＆カンファレンス 2025 • 北京＆豊橋",
    "s1_location": "北京＆豊橋 カンファレンス 2025",
    "s1_notes": "スライド 1: 北京・豊橋カンファレンスの皆様にご挨拶。クレメンス・クーネルトとルイス・レンナー社の紹介。モイゼルヴィッツ新本社への全工程統合という歴史的変革を強調。",
    "s2_category": "第1部：序論とモイゼルヴィッツ新拠点",
