    "s8_title": "カーディング（梳毛）：繊維の整列とフリース形成",
    "s8_subtitle": "Die definierte Faserorientierung als Fundament für Schwingung und Saitenansprache",
    "s8_bullet_1": "<strong>Kardieren (Carding):</strong> Die aufgelockerten Fasern werden über feine Nadelwalzen gekämmt, entwirrt und parallel zueinander angeordnet.",
    "s8_bullet_2": "<strong>Definierte Faserrichtung:</strong> Das so entstehende hauchdünne, weiche Vlies besitzt eine exakt vorgegebene Vorzugsrichtung der Fasern.",
    "s8_bullet_3": "<strong>Schichtung:</strong> Mehrere Vlieslagen werden im Kreuz- und Längsverbund übereinandergelegt, um die gewünschte Plattendicke und Dichteverteilung aufzubauen.",
    "s8_bullet_4": "<strong>Voraussetzung für die Intonation:</strong> Nur parallel geordnete Fasern reagieren bei späteren Intonierarbeiten vorhersehbar und gleichmäßig auf Nadelstiche.",
    "s8_caption_1": "Auskämmen der Wolle zu seidig fließenden Vliesen mit definierter Faserrichtung",
