    "s13_subtitle": "1 oder 2 farbige Schichten am Bass-Beginn als traditioneller Herkunftsnachweis",
    "s13_bullet_1": "<strong>Was ist die „Seele“?</strong> Eine dünne, andersfarbige Filzschicht, die bei der Plattenherstellung am Bassanfang eingearbeitet wird.",
    "s13_bullet_2": "<strong>Traditioneller Herkunftsnachweis:</strong> Ein historisches Echtheitsmerkmal der Filzfabrik Wurzen für Klavierbauer weltweit.",
    "s13_bullet_3": "<strong>Kein Qualitätsunterschied:</strong> Platten mit 1 oder 2 Seelen besitzen identische Fasereigenschaften – sie dienen der Chargenkennzeichnung und optischen Authentizität.",
