    "s5_m1_bullet_1": "<strong>1783年创立：</strong>约翰·丹克戈特·魏克特在乌尔岑奠定萨克森羊毛与高级制毡工艺传统。",
    "s5_m1_bullet_2": "<strong>精细毛毡先驱：</strong>传统手工工坊迅速壮大为欧洲顶尖的高端工业技术与声学纯羊毛毡制造中心。",
    "s5_m1_bullet_3": "<strong>深耕钢琴声学：</strong>极早专注于为方兴未艾的现代钢琴研制高弹性专属击弦介质。",
    "s5_m1_fact": "🏛 位于乌尔岑的全球历史最悠久工业羊毛毡制造企业",
    "s5_m1_caption": "从手工梳理的原生态羊毛薄毡到极高密度的魏克特专用整块毡料",
