    "s5_m2_bullet_1": "<strong>毛毡取代皮革：</strong>1847年首次成功以均质高弹性纯羊毛毡彻底替代坚硬不均的传统皮革包裹。",
    "s5_m2_bullet_2": "<strong>大师级卓越协同：</strong>魏克特的远见卓识与帕茨克的精湛制毡技艺强强联合，铸就全球声誉。",
    "s5_m2_bullet_3": "<strong>穆尔德河天然水质：</strong>穆尔德河矿物质极低的天然纯净软水，确保羊毛纤维得到最温和的纯净处理。",
    "s5_m2_fact": "🎹 行业里程碑：乌尔岑特级琴毡终结钢琴皮革击弦时代",
