    "s5_m3_badge": "享誉全球 1851",
    "s5_m3_title": "伦敦与巴黎世博会揽获世界金奖",
    "s5_m3_subtitle": "享誉国际并获萨克森王室御赐殊荣的至高毛毡品质",
    "s5_m3_bullet_1": "<strong>揽获世博金奖：</strong>接连斩获莱比锡（1850）、伦敦（1851）与巴黎（1867）最高世博金奖，名满天下。",
    "s5_m3_bullet_2": "<strong>国王亲临视察：</strong>萨克森王国历代君主亲临视察乌尔岑制造工场，盛赞其卓绝工艺。",
    "s5_m3_bullet_3": "<strong>欧洲名厂一致之选：</strong>维也纳、巴黎与伦敦的顶级钢琴制造大师全线指定采用魏克特毛毡。",
    "s5_m3_fact": "🏅 1851伦敦、1867巴黎及1850莱比锡世博金牌",
    "s5_m3_caption": "因极致毛毡工艺与纯净度而荣获的历史世博会珍藏金牌",
    "s5_m4_badge": "扩张 1861",
