    "s5_hl1_desc": "精选阿根廷、南非与新西兰顶级原毛的独家拼配配方：唯有将细长柔韧的长纤维羊毛与具备极强机械互锁特性的羊毛精准融合，方能成就抗拉强度极高、弹性充沛的顶级弦槌纯毛毡。",
