    "s27_c1_title": "拆箱即装 | 极速换装 | 跃升音质",
    "s27_c1_desc": "专为雅马哈C1、C2及C3量身定制，雷诺彻底颠覆了传统钢琴音槌更换流程。钢琴技师首次迎来出厂完成91°黄金角度精调并由天然骨胶预粘接的总成套件，开箱即可直接固定于击弦机总档铝轨。",
    "s27_bullet_1": "100% 即插即用：告别繁琐的车间钻孔打孔、反复角度测量与耗时上胶。",
    "s27_bullet_2": "乌尔岑顶级音乐会羊毛毡与黑胡桃木：赋予钢琴饱满温暖、极具穿透力的欧系歌唱性音色。",
    "s27_bullet_3": "单日极速交付：在客户现场或音乐厅舞台，约90分钟即可全套更换完毕。",
    "s27_caption_1": "德国雷诺官方原装雅马哈套件礼盒（C1-C3）与三分区高精度定位内衬托盘",
    "s27_notes": "雅马哈套件重磅发布。重点阐述节省10小时工时以及开箱即享的音乐会级音色。",
    "s28_category": "第四部分：雅马哈套件 • 车间工时对比",
