    "s38_notes": "第 58 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s39_category": "第七部分：钢琴整音大师秘籍",
    "s39_title": "初期预整音（Pre-Needling）：蓝色极强音楔区深度垂直扎针释放死应力",
    "s39_subtitle": "Abbau werkseitiger Vorspannung und Energieübertragung in den Forte-Keil",
    "s39_bullet_1": "<strong>Arbeitszone:</strong> Ausschließlich im blauen Fortissimo-Keil (Bereiche 9:00–10:00 Uhr und 2:00–3:00 Uhr).",
    "s39_bullet_2": "<strong>Tiefe Einstiche:</strong> Nadeln tief bis kurz vor den Unterfilz einstechen (niemals in Unterfilz oder Holzkern stechen!).",
    "s39_bullet_3": "<strong>Spannungstransfer:</strong> Der Kopf verliert die harte Werkssteife; elastische Spannungsenergie fließt in den grünen Forte-Keil ab.",
    "s39_bullet_4": "<strong>Empfehlung:</strong> Dieser Schritt ist vor dem ersten Anspielen im Instrument fast ausnahmslos anzuraten.",
    "s39_caption_1": "Pre-Needling: Tiefe Stiche im Fortissimo-Keil (9:00 bis 10:00 Uhr)",
    "s39_b1_badge": "基础刺针整音",
    "s39_b2_badge": "建立核心弹性",
    "s39_c1_desc": "预整音是全新出厂或重新包毡弦槌建立健康弹性基座的最核心声学工序：",
    "s39_notes": "第 59 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
