    "s40_subtitle": "Drücken statt Hacken – Exakte Stichanzahlen für Bass, Mittellage und Diskant",
    "s40_bullet_1": "<strong>Stichanzahlen Pre-Needling:</strong> <br>• Bass: 7–10 Stiche horizontal <br>• Mittellage: 5–10 Stiche horizontal <br>• Diskant: 0–7 Stiche vertikal",
    "s40_bullet_2": "<strong>Drücken, niemals hacken!</strong> Nadeln ruhig und mit Körpergewicht eindrücken. Hacken zerreißt die Wollfasern unkontrolliert!",
    "s40_bullet_3": "<strong>Original Renner Werkzeuge:</strong> <br>• Intonierapparat verstellbar (Art. 43-0005642) <br>• 3er-Intonierer Profi-Typ (Art. 43-0003270) <br>• Nadeln Nr. 7 vernickelt ø 0,60 mm, 9 mm lang (Art. 43-0003426).",
